import json
import logging
from enum import Enum
from pprint import pformat

import requests
from requests.auth import HTTPBasicAuth
from taf.internal.impact_radar import log_radar

from .exceptions import (MandatoryAttributesNotDefined,
                         NotSupportedAttributesDefined, NotSupportedFeature)

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CnumRestApi:
    TRIGGER_OPERATION_ENDPOINT = "sm-operations/api/sm/operations/v1/request/start/trigger-cnum-operation"
    TRIGGER_OPERATION_HEADERS = {
        "Content-Type": "application/vnd.nokia-sm-cnum-operation-request-v1+json;charset=utf-8",
        "Accept-Language": "en-US",
        "Cache-Control": "no-cache"
    }

    OPERATION_STATUS_ENDPOINT = "sm-operations/api/sm/operations/v1/request/status/cnum-operation-status"
    OPERATION_STATUS_HEADERS = {
        "Content-Type": "application/vnd.nokia-sm-status-request-v1+json;charset=utf-8",
        "Accept-Language": "en-US",
        "Cache-Control": "no-cache"
    }

    GENERATE_SUMMARY_ENDPOINT = "sm-operations/api/sm/operations/v1/execute/generate-cnum-summary"
    GENERATE_SUMMARY_HEADERS = {
        "Content-Type": "application/vnd.nokia-sm-summary-request-v1+json;charset=utf-8",
        "Accept-Language": "en-US",
        "Cache-Control": "no-cache"
    }

    GENERATE_REPORT_ENDPOINT = "sm-operations/api/sm/operations/v1/execute/generate-cnum-report"
    GENERATE_REPORT_HEADERS = {
        "Accept-Language": "en-US",
        "Cache-Control": "no-cache"
    }

    OPERATIONS = Enum('operation', {  # type: ignore[misc]
        'Activation': 'Activation',
        'Deactivation': 'Deactivation',
        'Reactivation': 'Reactivation'})

    NE_ID_TYPES = Enum('ne_id_type', {  # type: ignore[misc]
        'dn': 'dn',
        'name': 'name',
        'input_file': 'input_file'})

    LDAP_ACCESS_TYPES = Enum('ldap_access_type', {  # type: ignore[misc]
        'STARTTLS': 'STARTTLS',
        'PREFER TLS': 'PREFER TLS'})

    IP_TYPES = Enum('ip_type', {  # type: ignore[misc]
        'IPv4': 'IPV4',
        'IPv6': 'IPV6'})

    def __init__(self, web_url, username, password):
        self.web_url = web_url
        self.username = username
        self.password = password

    def trigger_operation(self, operation, ne_id_value, ne_id_type='dn', ldap_access_type=None,
                          ip_type=None, include_correlated_nes=None):
        """
        Trigger the CNUM Activation/Deactivation/Reactivation on a specific network element.
        Distinguished Name or Presentation Name must be specified as input for the network element.

        Example output::

            {
                "errorCode": 0,
                "errors": [],
                "errorMessage": None,
                "numberOfNes": 1,
                "operationId": "neac.cnum.1684834923827",
                "startTimeStamp": "15/06/2023 07:08:09 GMT",
                "status": "Started"
            }


        :param string operation: Specifies which CNUM operation is to be triggered for specified network element.
            Allowed values (case insensitive): `Activation`, `Deactivation` or `Reactivation`.
        :param string|list(dict) ne_id_value: Specifies network element(s) for which CNUM operation is to be triggered.
            If `ne_id_type` is `dn`, then NE's Distinguished Name must be set (as registered in Monitor).
            If `ne_id_type` is `name`, then NE's Presentation Name must be set (as configured in NE Integration Wizard).
            If `ne_id_type` is `input_file`, then list of NEs must be specified in list(dict) format, where each dict
           must contain at least `dnName` attribute:
                - dnName (string): (Mandatory) NE’s Distinguished Name.
                - ldapAccessType (string): (Optional): Allowed values: `PREFER TLS` or `STARTTLS`
                - ipType (string): (Optional): Allowed values: `IPv4` or `IPv6`
            If `ldapAccessType` and/or `ipType` attribute are not specified, then the values configured in
            `ldap_access_type` and/or `ip_type` are used. If `ldap_access_type` and/or `ip_type` are not specified,
            then default values supported by the specified network element type are used.
        :param string ne_id_type: Allowed values (case insensitive):
            - `dn` if NE’s Distinguished Name is set as `ne_id_value`.
            - `name` if NE’s Presentation Name is set as `ne_id_value`.
            - `input_file` if list of NEs is set as `ne_id_value`.
        :param string ldap_access_type: LDAP Access type to be configured in network element while triggering CNUM
            activation operation. Optional for `Activation` operation type. Not needed or ignored if specified,
            for `Deactivation` and `Reactivation` operation types. Allowed values (case insensitive): `PREFER TLS`
            or `STARTTLS`. If not specified during activation, then the default LDAP Access Type supported by the
            specified network element type is used.
        :param string ip_type: IP type configured in network element while triggering CNUM activation operation.
            Optional for `Activation` operation type. Not needed or ignored if specified, for `Deactivation` and
            `Reactivation` operation types. Allowed values (case insensitive): `IPv4` or `IPv6`. If not specified
            during activation, then the default IP Type supported by the specified network element type is used.
        :param bool include_correlated_nes: IP type configured in network element while triggering CNUM operation.
            If `False`, then triggered CNUM operation is performed only on the specified network element
            and not on co-related network elements even if they exist. If not set, then the default value is `False`.
            This flag is provided for network elements that have a PARENT-CHILD correlation. That is, NADA adaptation
            parameter correlationType equals PARENT or CHILD, e.g. RNC and VNF. For such correlated network elements
            it is recommended to have same CNUM status.
        :return: Status of operation.
        :rtype: dict
        """
        operation = self.OPERATIONS(operation.capitalize()).name
        ldap_access_type = self.LDAP_ACCESS_TYPES(ldap_access_type.upper()).name if ldap_access_type else None
        ip_type = self.IP_TYPES(ip_type.upper()).name if ip_type else None

        if operation == 'Reactivation' and ne_id_type == 'input_file':
            exc_msg = "input_file as ne_id_type is not supported by Reactivation operation"
            raise NotSupportedFeature(exc_msg)

        self._validate_ne_id_settings(ne_id_type, ne_id_value)

        data = {
            "operation": operation,
            "neIdType": ne_id_type,
            "neIdValue": ne_id_value,
            "ldapAccessType": ldap_access_type,
            "ipType": ip_type,
            "includeCorrelatedNes": include_correlated_nes,
        }
        return self._post(self.TRIGGER_OPERATION_ENDPOINT,
                          self.TRIGGER_OPERATION_HEADERS,
                          self._filter_data(data))

    def get_operation_status(self, operation_id):
        """
        Get the status of any Activation/Deactivation/Reactivation operation triggered in the past.

        Example output::

            {
                "activationState": None,
                "completionTime": None,
                "errors": [],
                "statusMsg": "1 out of 1 Operation(s) scheduled are completed. "
                             "Successful = 1, Partly Successful = 0, Failed = 0, Ongoing = 0",
                "startTimeStamp": "15/06/2023 09:18:55 GMT",
                "operationStatus": "Completed"
            }

        :param string operation_id: CNUM operation Job ID for which status is to be obtained,
            e.g. `neac.cnum.1684763709257`
        :return: Status of operation.

            {
                "operationStatus": "Completed/Ongoing",
                "statusMsg": "y out of x Operation(s) scheduled are completed. "
                           "Successful = a, Partly Successful = b, Failed = c, Ongoing = d"
            }

            where:
                - `operationStatus`: This value can be `Completed` if the operation is completed or in `Ongoing` state
                    if at least for one network element the CNUM operation is still in progress.
                - `statusMsg`: Message should contain number of operations completed and number of operations
                    that are in `Ongoing`, `Failed` and `Partly successful` state.
                        - `x`: Total number of operations scheduled.
                        - `y`: Number of scheduled operations that are completed.
                        - `a`: Number of completed operations that are successful.
                        - `b`: Number of completed operations that are partly successful.
                        - `c`: Number of completed operations that are failed.
                        - `d`: Number of scheduled operations that are ongoing.

        :rtype: dict
        """
        data = {
            "operationId": operation_id
        }
        return self._post(self.OPERATION_STATUS_ENDPOINT,
                          self.OPERATION_STATUS_HEADERS,
                          data)

    def generate_summary(self, ne_id_value, ne_id_type='dn'):
        """
        Generate and return a report summarizing the CNUM status for all network elements provided as input.

        Example output::

            {
                "errors": [],
                "startTimeStamp": "15/06/2023 09:10:10 GMT",
                "summaryPath": "/var/opt/oss/global/neac/cnum-operation-data/CNUMSummary_1686647410682775.csv",
                "summaryStatus": "successful"
            }

        :param string|list(dict) ne_id_value: Specifies network element(s) for which CNUM summary is to be generated.
            If `ne_id_type` is `dn`, then NE's Distinguished Name must be set (as registered in Monitor).
            If `ne_id_type` is `name`, then NE's Presentation Name must be set (as configured in NE Integration Wizard).
            If `ne_id_type` is `input_file`, then list of NEs must be specified in list(dict) format, where each dict
            must contain ``dnName`` attribute:
                - dnName (string): NE’s Distinguished Name.
        :param string ne_id_type: Allowed values:
            - `dn` if NE’s Distinguished Name is set as `ne_id_value`.
            - `name` if NE’s Presentation Name is set as `ne_id_value`.
            - `input_file` if list of NEs is set as `ne_id_value`.
        :return: Report summarizing the CNUM status for all network elements provided as input.

            {
                "status": "Successful/Failed",
                "summaryPath": "Full Path of report"
            }

            For each network element following parameter values are returned in csv format in the generated summary report:
                - DN of NE
                - NE Name (if configured)
                - NE Release
                - NE Type
                - LDAP Access Type
                - IP Type
                - CNUM Status
                - Last Operation Time

        :rtype: dict
        """
        self._validate_ne_id_settings(ne_id_type, ne_id_value)

        data = {
            "neIdType": ne_id_type,
            "neIdValue": ne_id_value
        }
        return self._post(self.GENERATE_SUMMARY_ENDPOINT,
                          self.GENERATE_SUMMARY_HEADERS,
                          data)

    def generate_report(self):
        """
        Generate and return a report summarizing the current CNUM status of all network elements
        that are integrated to the NetAct Cluster and support CNUM provisioning.

        Example output::

            {
                "errors": [],
                "failureReason": "",
                "reportPath": "/var/opt/oss/global/neac/cnum-operation-data/CNUMReport_1686648275321977.csv",
                "reportStatus": "successful",
                "startTimeStamp": "15/06/2023 09:24:35 GMT"
            }

        :return: Report summarizing the current CNUM status of all network elements
            that are integrated to the NetAct Cluster and support CNUM provisioning.

                {
                    "status": "Successful/Failed",
                    "reportPath": "Full Path of report"
                }

            For each network element integrated to NetAct and supporting CNUM, following parameter
            values are returned in the csv format in the generated summary report:
               - DN of NE
               - NE Name (if configured)
               - MR to which NE is mapped
               - NE Release
               - NE Type
               - LDAP Access Type
               - IP Type
               - CNUM Status
               - Last Operation Time

        :rtype: dict
        """
        return self._post(self.GENERATE_REPORT_ENDPOINT,
                          self.GENERATE_REPORT_HEADERS)

    def _request(self, method, endpoint, **kwargs):
        auth = HTTPBasicAuth(username=self.username, password=self.password)
        url = f'https://{self.web_url}/{endpoint}'

        log_radar(
            "Sending NetAct request",
            request_method=method,
            request_url=url,
            request_params=kwargs.get("params"),
            request_data=kwargs.get("data"),
        )
        response = requests.request(method, url, auth=auth, verify=False, **kwargs)
        response.raise_for_status()
        response_json = response.json()
        logger.debug(f'Response: \n{pformat(response_json)}')
        return response_json

    def _post(self, endpoint, headers, data=None):
        data = json.dumps(data) if data else None
        return self._request('POST', endpoint, headers=headers, data=data)

    @staticmethod
    def _filter_data(data):
        """
        Filter the data body content by removing items with empty value.
        """
        return {k: v for k, v in data.items() if v}

    def _validate_ne_id_settings(self, ne_id_type, ne_id_value):
        ne_id_type = self.NE_ID_TYPES(ne_id_type.lower()).name if ne_id_type else None
        allowed_keys = {'dnName', 'name', 'ldapAccessType', 'ipType'}
        if ne_id_type == 'input_file':
            not_supported_keys = set()
            missing_keys_counter = 0
            for element in ne_id_value:
                not_supported_keys.update(set(element).difference(allowed_keys))
                missing_keys_counter += (1 if 'dnName' not in element else 0)
            if missing_keys_counter:
                exc_msg = (f"Mandatory 'dnName' attribute is not defined in "
                           f"{missing_keys_counter} element(s) of ne_id_value")
                raise MandatoryAttributesNotDefined(exc_msg)
            if not_supported_keys:
                exc_msg = (f"Not supported attributes defined in element(s) "
                           f"of ne_id_value: {', '.join(not_supported_keys)}")
                raise NotSupportedAttributesDefined(exc_msg)
        elif not isinstance(ne_id_value, str):
            exc_msg = (f"ne_id_value must be string type for 'dn' or "
                       f"'name' ne_id_type, not {type(ne_id_value)}")
            raise TypeError(exc_msg)
